/**
 * B140 — BUNDLE BASE (DeepSeek Harness `packages/bundle/base` mirror,
 * JEXI-branded).
 *
 * JEXI's shared core as a composition manifest: the "bundle" lists every
 * DeepSeek Harness package JEXI has pulled and its JEXI port/status, so
 * the pull-all work is observable and auditable.
 *
 *   bundleStatus() → { manifest, counts, live }
 *
 * The manifest lives at server/bundles/manifest.json (regenerated by
 * scripts/audit-bundles.js); DSH-PARITY.md at the repo root is the
 * human-readable tracker.
 */

import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';
import { TOOL_COUNT, TOOL_REGISTRY } from './ToolRegistry.js';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
export const BUNDLES_DIR = path.resolve(__dirname, '..', '..', 'bundles');
export const MANIFEST_FILE = path.join(BUNDLES_DIR, 'manifest.json');
export const PARITY_FILE = path.resolve(__dirname, '..', '..', '..', 'DSH-PARITY.md');

/** Read the parity manifest (missing file → empty list). */
export function readBundleManifest() {
  try {
    if (fs.existsSync(MANIFEST_FILE)) {
      const parsed = JSON.parse(fs.readFileSync(MANIFEST_FILE, 'utf-8'));
      if (parsed && Array.isArray(parsed.packages)) return parsed;
    }
  } catch { /* fresh */ }
  return { generatedAt: null, packages: [] };
}

/** Live bundle status: manifest + current registry facts. */
export function bundleStatus() {
  const manifest = readBundleManifest();
  const packages = manifest.packages || [];
  const counts = {
    total: packages.length,
    ported: packages.filter((p) => p.status === 'ported').length,
    partial: packages.filter((p) => p.status === 'partial').length,
    notYet: packages.filter((p) => p.status === 'not-yet' || !p.status).length,
  };
  return {
    ok: true,
    generatedAt: manifest.generatedAt || null,
    counts,
    registryTools: TOOL_COUNT,
    registrySlugs: TOOL_REGISTRY.map((t) => t.slug),
    packages: packages.map((p) => ({
      package: p.package,
      area: p.area || 'misc',
      status: p.status || 'not-yet',
      port: p.port || null,
      batch: p.batch || null,
      note: p.note || '',
    })),
  };
}

/** Whether a package slug appears in the registry (used by the audit). */
export function packageIsInRegistry(slug) {
  return TOOL_REGISTRY.some((t) => t.slug === slug);
}
